-- Run this SQL in your Supabase Project -> SQL Editor -> New Query -> Run
-- ==========================================================================

-- 1. Create table
CREATE TABLE IF NOT EXISTS detections (
    id BIGSERIAL PRIMARY KEY,
    entry_date DATE NOT NULL DEFAULT CURRENT_DATE,
    buyer TEXT NOT NULL,
    supplier TEXT NOT NULL,
    product TEXT NOT NULL,
    product_range TEXT NOT NULL,
    propo_canceled BOOLEAN DEFAULT FALSE,
    affaire_created BOOLEAN DEFAULT FALSE,
    affaire_date DATE,
    affaire_number TEXT,
    rejected_affair BOOLEAN DEFAULT FALSE,
    affaire_sent BOOLEAN DEFAULT FALSE,
    offer_received BOOLEAN DEFAULT FALSE,
    offer_date DATE,
    offer_number TEXT,
    offer_value NUMERIC(12, 2) DEFAULT 0.00,
    status TEXT,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Enable Row Level Security (RLS)
ALTER TABLE detections ENABLE ROW LEVEL SECURITY;

-- 3. Create Public Access Policy (for simple team access)
DROP POLICY IF EXISTS "Allow public full access" ON detections;
CREATE POLICY "Allow public full access" ON detections FOR ALL USING (true) WITH CHECK (true);

